def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]
    if old_value == 0:
        return None

    signed_change = new_value - old_value
    change_ratio = signed_change / old_value
    value = change_ratio * 100

    return {
        "value": value,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "signed_change": signed_change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
